const updateStorageTarget = `-- name: UpdateStorageTarget :one
UPDATE storage_targets
SET name = $1, endpoint = $2, bucket = $3, prefix = $4, region = $5,
    path_style = $6, credentials = $7, updated_at = now()
WHERE id = $8 AND deleted_at IS NULL
RETURNING id, name, endpoint, bucket, prefix, credentials, is_default, created_at, org_id, region, path_style, created_by, updated_at, deleted_at, xenibase_region
`

type UpdateStorageTargetParams struct {
	Name        string
	Endpoint    string
	Bucket      string
	Prefix      string
	Region      string
	PathStyle   bool
	Credentials []byte
	ID          uuid.UUID
}

// tenant: system - the caller loaded the target through its org_id (or as a platform target) first.
func (q *Queries) UpdateStorageTarget(ctx context.Context, arg UpdateStorageTargetParams) (StorageTarget, error) {
	row := q.db.QueryRow(ctx, updateStorageTarget,
		arg.Name,
		arg.Endpoint,
		arg.Bucket,
		arg.Prefix,
		arg.Region,
		arg.PathStyle,
		arg.Credentials,
		arg.ID,
	)
	var i StorageTarget
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Endpoint,
		&i.Bucket,
		&i.Prefix,
		&i.Credentials,
		&i.IsDefault,
		&i.CreatedAt,
		&i.OrgID,
		&i.Region,
		&i.PathStyle,
		&i.CreatedBy,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.XenibaseRegion,
	)
	return i, err
}
